            /// The name of the pool. It must be unique.
            public var name: String?
            /// Set if deep-scrubbing is disabled for this pool.
            public var nodeepScrub: Bool?
            /// Set if pool delete is blocked.
            public var nodelete: Bool?
            /// Set if changing the placement-group count is blocked.
            public var nopgchange: Bool?
            /// Set if scrubbing is disabled for this pool.
            public var noscrub: Bool?
            /// Set if changing the replication size is blocked.
            public var nosizechange: Bool?
            /// The automatic PG scaling mode of the pool.
            public var pgAutoscaleMode: String?
            /// Number of placement groups.
            public var pgNum: Int?
            /// Minimal number of placement groups.
            public var pgNumMin: Int?
            /// Placement-group-for-placement count.
            public var pgpNum: Int?
            /// Number of replicas per object
            public var size: Int?
            /// Optional pool usage and IO statistics (only present when verbose=1 is requested).
            public var statistics: JSONValue?
            /// The estimated target size of the pool for the PG autoscaler.
            public var targetSize: String?
            /// The estimated target ratio of the pool for the PG autoscaler.
            public var targetSizeRatio: Double?
            /// Set if hitsets use GMT timestamps (for cache-tier pools).
            public var useGmtHitset: Bool?
            /// Set if the pool sets the FADV_DONTNEED hint on writes.
            public var writeFadviseDontneed: Bool?

            public init(from decoder: any Decoder) throws {
                let c = try decoder.container(keyedBy: AnyCodingKey.self)
                application = c.flexibleString(AnyCodingKey("application"))
                applicationList = c.lenientArray(String.self, forKey: AnyCodingKey("application_list"))
                autoscaleStatus = try? c.decodeIfPresent(JSONValue.self, forKey: AnyCodingKey("autoscale_status"))
                crushRule = c.flexibleString(AnyCodingKey("crush_rule"))
                fastRead = c.flexibleBool(AnyCodingKey("fast_read"))
                hashpspool = c.flexibleBool(AnyCodingKey("hashpspool"))
                id = c.flexibleInt(AnyCodingKey("id"))
                minSize = c.flexibleInt(AnyCodingKey("min_size"))
                name = c.flexibleString(AnyCodingKey("name"))
                nodeepScrub = c.flexibleBool(AnyCodingKey("nodeep-scrub"))
                nodelete = c.flexibleBool(AnyCodingKey("nodelete"))
                nopgchange = c.flexibleBool(AnyCodingKey("nopgchange"))
                noscrub = c.flexibleBool(AnyCodingKey("noscrub"))
                nosizechange = c.flexibleBool(AnyCodingKey("nosizechange"))
                pgAutoscaleMode = c.flexibleString(AnyCodingKey("pg_autoscale_mode"))
                pgNum = c.flexibleInt(AnyCodingKey("pg_num"))
                pgNumMin = c.flexibleInt(AnyCodingKey("pg_num_min"))
                pgpNum = c.flexibleInt(AnyCodingKey("pgp_num"))
                size = c.flexibleInt(AnyCodingKey("size"))
                statistics = try? c.decodeIfPresent(JSONValue.self, forKey: AnyCodingKey("statistics"))
                targetSize = c.flexibleString(AnyCodingKey("target_size"))
                targetSizeRatio = c.flexibleDouble(AnyCodingKey("target_size_ratio"))
                useGmtHitset = c.flexibleBool(AnyCodingKey("use_gmt_hitset"))
                writeFadviseDontneed = c.flexibleBool(AnyCodingKey("write_fadvise_dontneed"))
            }
        }
    }

